package com.example.finance;

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.control.TabPane;
import javafx.stage.Stage;

public class MainApp extends Application {

    @Override
    public void start(Stage stage) {
        DataPaths dataPaths = new DataPaths();
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        CategoryService categoryService = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        RecurringObligationService recurringObligationService = new RecurringObligationService(
                recurringObligationRepository, transactionRepository, categoryRepository, categoryService);
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);
        SavingsGoalService savingsGoalService = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository, categoryService);
        MonthSummaryService monthSummaryService = new MonthSummaryService(
                budgetService, savingsGoalService, recurringObligationService);

        MonthSummaryView monthSummaryView = new MonthSummaryView(monthSummaryService);
        TransactionEntryView transactionEntryView = new TransactionEntryView(categoryRepository, transactionRepository);
        CategorySummaryView categorySummaryView = new CategorySummaryView(
                categoryRepository, categoryService, budgetService);
        SavingsGoalsView savingsGoalsView = new SavingsGoalsView(
                savingsGoalRepository, goalContributionRepository, savingsGoalService);
        RecurringObligationsView recurringObligationsView = new RecurringObligationsView(
                recurringObligationRepository, recurringObligationService);

        TabPane tabPane = new TabPane();
        tabPane.getTabs().addAll(
                monthSummaryView.asTab(),
                transactionEntryView.asTab(),
                categorySummaryView.asTab(),
                savingsGoalsView.asTab(),
                recurringObligationsView.asTab());

        // Entering any tab re-pulls the latest data, since transactions/goals/
        // obligations/categories entered in one tab feed the totals shown in the others.
        tabPane.getSelectionModel().selectedItemProperty().addListener((obs, oldTab, newTab) -> {
            transactionEntryView.refresh();
            categorySummaryView.refresh();
            savingsGoalsView.refresh();
            recurringObligationsView.refresh();
            monthSummaryView.refresh();
        });

        stage.setTitle("Personal Finance");
        stage.setScene(new Scene(tabPane, 1024, 720));
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * Category totals, leftover, and over-budget flags for a given month.
 * Takes the month explicitly (never assumes "now") so a future history view
 * can call this the same way for any past month. A category's actual is
 * strictly its own logged transactions — obligations are their own
 * categories now, so there's nothing else to fold in.
 */
public class BudgetService {

    private final CategoryRepository categoryRepository;
    private final TransactionRepository transactionRepository;

    public BudgetService(CategoryRepository categoryRepository, TransactionRepository transactionRepository) {
        this.categoryRepository = categoryRepository;
        this.transactionRepository = transactionRepository;
    }

    public List<CategoryTotal> categoryTotals(YearMonth month) {
        List<CategoryTotal> totals = new ArrayList<>();
        for (Category category : categoryRepository.findAll()) {
            // Categories don't carry an income/expense type, so a category's
            // actual is every transaction logged against it, whichever way
            // the money moved — otherwise an income category (e.g. a
            // paycheck) would always show zero actual.
            BigDecimal actual = sumTransactions(month, null, category.getName());
            totals.add(new CategoryTotal(category, actual, isIncomeOnlyCategory(category.getName())));
        }
        return totals;
    }

    /**
     * True if every transaction ever logged against this category is
     * income (e.g. a "Paycheck" category) — used to keep income out of
     * spending-oriented views like charts without needing a stored
     * category type.
     */
    private boolean isIncomeOnlyCategory(String categoryName) {
        List<Transaction> matching = transactionRepository.findAll().stream()
                .filter(t -> t.getCategoryName().equals(categoryName))
                .toList();
        return !matching.isEmpty() && matching.stream().allMatch(t -> t.getType() == TransactionType.INCOME);
    }

    public BigDecimal totalIncome(YearMonth month) {
        return sumTransactions(month, TransactionType.INCOME, null);
    }

    public BigDecimal totalExpenses(YearMonth month) {
        return sumTransactions(month, TransactionType.EXPENSE, null);
    }

    public BigDecimal leftover(YearMonth month) {
        return totalIncome(month).subtract(totalExpenses(month));
    }

    private BigDecimal sumTransactions(YearMonth month, TransactionType type, String categoryName) {
        return transactionRepository.findAll().stream()
                .filter(t -> type == null || t.getType() == type)
                .filter(t -> categoryName == null || t.getCategoryName().equals(categoryName))
                .filter(t -> YearMonth.from(t.getDate()).equals(month))
                .map(Transaction::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public static class CategoryTotal {
        private final Category category;
        private final BigDecimal actual;
        private final boolean incomeOnly;

        public CategoryTotal(Category category, BigDecimal actual) {
            this(category, actual, false);
        }

        public CategoryTotal(Category category, BigDecimal actual, boolean incomeOnly) {
            this.category = category;
            this.actual = actual;
            this.incomeOnly = incomeOnly;
        }

        public Category getCategory() {
            return category;
        }

        public BigDecimal getActual() {
            return actual;
        }

        public BigDecimal getRemaining() {
            return category.getMonthlyTarget().subtract(actual);
        }

        public boolean isOverBudget() {
            return actual.compareTo(category.getMonthlyTarget()) > 0;
        }

        public boolean isIncomeOnly() {
            return incomeOnly;
        }
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/**
 * Thin facade assembling BudgetService/SavingsGoalService/RecurringObligationService
 * output into one object for the month summary dashboard.
 */
public class MonthSummaryService {

    private final BudgetService budgetService;
    private final SavingsGoalService savingsGoalService;
    private final RecurringObligationService recurringObligationService;

    public MonthSummaryService(BudgetService budgetService, SavingsGoalService savingsGoalService,
                                RecurringObligationService recurringObligationService) {
        this.budgetService = budgetService;
        this.savingsGoalService = savingsGoalService;
        this.recurringObligationService = recurringObligationService;
    }

    public MonthSummary summarize(YearMonth month, LocalDate today) {
        List<BudgetService.CategoryTotal> categoryTotals = budgetService.categoryTotals(month);
        long overBudgetCount = categoryTotals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();

        return new MonthSummary(
                categoryTotals,
                budgetService.totalIncome(month),
                budgetService.totalExpenses(month),
                budgetService.leftover(month),
                savingsGoalService.availableLeftover(month),
                overBudgetCount,
                savingsGoalService.goalProgress(),
                recurringObligationService.upcomingPayments(today));
    }

    public static class MonthSummary {
        private final List<BudgetService.CategoryTotal> categoryTotals;
        private final BigDecimal totalIncome;
        private final BigDecimal totalExpenses;
        private final BigDecimal leftover;
        private final BigDecimal availableLeftover;
        private final long overBudgetCount;
        private final List<SavingsGoalService.GoalProgress> goalProgress;
        private final List<RecurringObligationService.UpcomingPayment> upcomingPayments;

        public MonthSummary(List<BudgetService.CategoryTotal> categoryTotals, BigDecimal totalIncome,
                             BigDecimal totalExpenses, BigDecimal leftover, BigDecimal availableLeftover,
                             long overBudgetCount, List<SavingsGoalService.GoalProgress> goalProgress,
                             List<RecurringObligationService.UpcomingPayment> upcomingPayments) {
            this.categoryTotals = categoryTotals;
            this.totalIncome = totalIncome;
            this.totalExpenses = totalExpenses;
            this.leftover = leftover;
            this.availableLeftover = availableLeftover;
            this.overBudgetCount = overBudgetCount;
            this.goalProgress = goalProgress;
            this.upcomingPayments = upcomingPayments;
        }

        public List<BudgetService.CategoryTotal> getCategoryTotals() {
            return categoryTotals;
        }

        public BigDecimal getTotalIncome() {
            return totalIncome;
        }

        public BigDecimal getTotalExpenses() {
            return totalExpenses;
        }

        public BigDecimal getLeftover() {
            return leftover;
        }

        public BigDecimal getAvailableLeftover() {
            return availableLeftover;
        }

        public long getOverBudgetCount() {
            return overBudgetCount;
        }

        public List<SavingsGoalService.GoalProgress> getGoalProgress() {
            return goalProgress;
        }

        public List<RecurringObligationService.UpcomingPayment> getUpcomingPayments() {
            return upcomingPayments;
        }
    }
}

package com.example.finance;

import javafx.collections.FXCollections;
import javafx.geometry.Insets;
import javafx.scene.chart.BarChart;
import javafx.scene.chart.CategoryAxis;
import javafx.scene.chart.NumberAxis;
import javafx.scene.chart.PieChart;
import javafx.scene.chart.XYChart;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.layout.VBox;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/**
 * The "awareness budgeting" dashboard: leftover, warnings, goal and
 * upcoming-payment callouts, and the two headline charts, all for one month.
 */
public class MonthSummaryView {

    private final MonthSummaryService monthSummaryService;
    private final YearMonth month;

    private final VBox root = new VBox(12);
    private final Label leftoverLabel = new Label();
    private final Label warningLabel = new Label();
    private final Label goalsLabel = new Label();
    private final Label upcomingLabel = new Label();
    private final VBox chartsBox = new VBox(12);

    public MonthSummaryView(MonthSummaryService monthSummaryService) {
        this(monthSummaryService, YearMonth.now());
    }

    public MonthSummaryView(MonthSummaryService monthSummaryService, YearMonth month) {
        this.monthSummaryService = monthSummaryService;
        this.month = month;
        buildLayout();
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Month Summary", root);
        tab.setClosable(false);
        return tab;
    }

    private void buildLayout() {
        for (Label label : List.of(leftoverLabel, warningLabel, goalsLabel, upcomingLabel)) {
            label.setWrapText(true);
        }
        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> refresh());
        root.setPadding(new Insets(12));
        root.getChildren().addAll(leftoverLabel, warningLabel, goalsLabel, upcomingLabel, chartsBox, refreshButton);
    }

    public void refresh() {
        MonthSummaryService.MonthSummary summary = monthSummaryService.summarize(month, LocalDate.now());

        leftoverLabel.setText(String.format("Income %s − Expenses %s = Leftover %s (available to allocate: %s)",
                summary.getTotalIncome(), summary.getTotalExpenses(), summary.getLeftover(),
                summary.getAvailableLeftover()));

        warningLabel.setText(summary.getOverBudgetCount() == 0
                ? "All categories are within target."
                : summary.getOverBudgetCount() + " categor"
                        + (summary.getOverBudgetCount() == 1 ? "y is" : "ies are") + " over budget.");

        long goalsReached = summary.getGoalProgress().stream()
                .filter(g -> g.getSavedAmount().compareTo(g.getGoal().getTargetAmount()) >= 0)
                .count();
        goalsLabel.setText(summary.getGoalProgress().size() + " savings goal(s), " + goalsReached + " reached.");

        upcomingLabel.setText(summary.getUpcomingPayments().size() + " payment(s) due in the next 60 days.");

        chartsBox.getChildren().setAll(buildPieChart(summary), buildBarChart(summary));
    }

    private PieChart buildPieChart(MonthSummaryService.MonthSummary summary) {
        List<PieChart.Data> slices = summary.getCategoryTotals().stream()
                .filter(t -> !t.isIncomeOnly())
                .filter(t -> t.getActual().signum() > 0)
                .map(t -> new PieChart.Data(t.getCategory().getName(), t.getActual().doubleValue()))
                .toList();
        PieChart pieChart = new PieChart(FXCollections.observableArrayList(slices));
        pieChart.setTitle("Spending by category");
        return pieChart;
    }

    private BarChart<String, Number> buildBarChart(MonthSummaryService.MonthSummary summary) {
        BarChart<String, Number> barChart = new BarChart<>(new CategoryAxis(), new NumberAxis());
        barChart.setTitle("Target vs. actual by category");

        XYChart.Series<String, Number> targetSeries = new XYChart.Series<>();
        targetSeries.setName("Target");
        XYChart.Series<String, Number> actualSeries = new XYChart.Series<>();
        actualSeries.setName("Actual");

        // Income categories (e.g. a paycheck) are excluded — both charts
        // are about spending, and mixing income in would either dwarf real
        // spending slices or look like a wildly underspent category.
        for (BudgetService.CategoryTotal total : summary.getCategoryTotals()) {
            if (total.isIncomeOnly()) {
                continue;
            }
            String name = total.getCategory().getName();
            targetSeries.getData().add(new XYChart.Data<>(name, total.getCategory().getMonthlyTarget().doubleValue()));
            actualSeries.getData().add(new XYChart.Data<>(name, total.getActual().doubleValue()));
        }

        barChart.getData().addAll(targetSeries, actualSeries);
        return barChart;
    }
}

package com.example.finance;

import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.ComboBox;
import javafx.scene.control.DatePicker;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;
import javafx.stage.FileChooser;
import javafx.stage.Window;

import java.io.File;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.Comparator;
import java.util.List;

/**
 * Transaction entry/edit/delete for the current month. Categories themselves
 * are managed on the Categories tab; this view just picks from what's there.
 */
public class TransactionEntryView {

    private final CategoryRepository categoryRepository;
    private final TransactionRepository transactionRepository;

    private final ObservableList<Category> categoryOptions = FXCollections.observableArrayList();
    private final ObservableList<Transaction> monthTransactions = FXCollections.observableArrayList();

    public TransactionEntryView(CategoryRepository categoryRepository, TransactionRepository transactionRepository) {
        this.categoryRepository = categoryRepository;
        this.transactionRepository = transactionRepository;
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Transactions", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        categoryOptions.setAll(categoryRepository.findAll());
        refreshTransactions();
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildTransactionManagement());
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildTransactionManagement() {
        DatePicker datePicker = new DatePicker(LocalDate.now());
        ComboBox<TransactionType> typeBox = new ComboBox<>(FXCollections.observableArrayList(TransactionType.values()));
        typeBox.setValue(TransactionType.EXPENSE);
        ComboBox<Category> categoryBox = new ComboBox<>(categoryOptions);
        TextField amountField = new TextField();
        amountField.setPromptText("Amount");
        TextField descriptionField = new TextField();
        descriptionField.setPromptText("Description");
        Label status = new Label();
        status.setWrapText(true);

        TableView<Transaction> table = buildTransactionTable();

        Button saveButton = new Button("Add transaction");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);
        Button importCsvButton = new Button("Import CSV");

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                datePicker.setValue(newSelection.getDate());
                typeBox.setValue(newSelection.getType());
                categoryOptions.stream()
                        .filter(c -> c.getName().equals(newSelection.getCategoryName()))
                        .findFirst()
                        .ifPresent(categoryBox::setValue);
                amountField.setText(newSelection.getAmount().toString());
                descriptionField.setText(newSelection.getDescription());
                saveButton.setText("Update transaction");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add transaction");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            LocalDate date = datePicker.getValue();
            TransactionType type = typeBox.getValue();
            Category category = categoryBox.getValue();
            if (date == null || type == null || category == null) {
                status.setText("Date, type, and category are required.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                String description = descriptionField.getText().trim();
                Transaction selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    transactionRepository.add(date, type, category.getName(), amount, description);
                    status.setText("Added transaction.");
                } else {
                    transactionRepository.update(selected.getId(), date, type, category.getName(), amount, description);
                    status.setText("Updated transaction.");
                }
                table.getSelectionModel().clearSelection();
                amountField.clear();
                descriptionField.clear();
                refreshTransactions();
            } catch (NumberFormatException ex) {
                status.setText("Amount must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            Transaction selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            transactionRepository.remove(selected.getId());
            table.getSelectionModel().clearSelection();
            status.setText("Deleted transaction.");
            refreshTransactions();
        });

        importCsvButton.setOnAction(e -> {
            FileChooser chooser = new FileChooser();
            chooser.setTitle("Import Transactions CSV");
            chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV files", "*.csv"));
            Window window = ((Node) e.getSource()).getScene().getWindow();
            File file = chooser.showOpenDialog(window);
            if (file == null) {
                return;
            }
            try {
                TransactionCsvImporter.ImportResult result = new TransactionCsvImporter().importFile(file.toPath());
                List<Transaction> imported = transactionRepository.addAll(result.rows());
                status.setText(summarizeImport(imported.size(), result.errors()));
                table.getSelectionModel().clearSelection();
                refreshTransactions();
            } catch (TransactionCsvImportException ex) {
                status.setText("Import failed: " + ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Transaction:"), datePicker, typeBox, categoryBox,
                amountField, descriptionField, saveButton, deleteButton, importCsvButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<Transaction> buildTransactionTable() {
        TableView<Transaction> table = new TableView<>(monthTransactions);

        TableColumn<Transaction, LocalDate> dateCol = new TableColumn<>("Date");
        dateCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getDate()));

        TableColumn<Transaction, TransactionType> typeCol = new TableColumn<>("Type");
        typeCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getType()));

        TableColumn<Transaction, String> categoryCol = new TableColumn<>("Category");
        categoryCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getCategoryName()));

        TableColumn<Transaction, BigDecimal> amountCol = new TableColumn<>("Amount");
        amountCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getAmount()));

        TableColumn<Transaction, String> descriptionCol = new TableColumn<>("Description");
        descriptionCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getDescription()));

        table.getColumns().addAll(dateCol, typeCol, categoryCol, amountCol, descriptionCol);
        return table;
    }

    private String summarizeImport(int imported, List<TransactionCsvImporter.RowError> errors) {
        int total = imported + errors.size();
        StringBuilder summary = new StringBuilder("Imported " + imported + " of " + total + " rows.");
        if (!errors.isEmpty()) {
            summary.append(" ").append(errors.size()).append(" skipped: ");
            errors.stream().limit(3).forEach(err ->
                    summary.append("Row ").append(err.rowNumber()).append(": ").append(err.reason()).append("; "));
            if (errors.size() > 3) {
                summary.append("(+").append(errors.size() - 3).append(" more - see console log)");
            }
        }
        return summary.toString();
    }

    private void refreshTransactions() {
        YearMonth currentMonth = YearMonth.now();
        monthTransactions.setAll(transactionRepository.findAll().stream()
                .filter(t -> YearMonth.from(t.getDate()).equals(currentMonth))
                .sorted(Comparator.comparing(Transaction::getDate))
                .toList());
    }
}

package com.example.finance;

import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableRow;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.List;

/**
 * Category creation/edit/delete, plus category vs. target vs. actual for
 * the current month, with over-budget rows highlighted and a warning
 * summary above the table.
 */
public class CategorySummaryView {

    private final CategoryRepository categoryRepository;
    private final CategoryService categoryService;
    private final BudgetService budgetService;
    private final YearMonth month;

    private final ObservableList<BudgetService.CategoryTotal> rows = FXCollections.observableArrayList();
    private final Label warningLabel = new Label();

    public CategorySummaryView(CategoryRepository categoryRepository, CategoryService categoryService,
                                BudgetService budgetService) {
        this(categoryRepository, categoryService, budgetService, YearMonth.now());
    }

    public CategorySummaryView(CategoryRepository categoryRepository, CategoryService categoryService,
                                BudgetService budgetService, YearMonth month) {
        this.categoryRepository = categoryRepository;
        this.categoryService = categoryService;
        this.budgetService = budgetService;
        this.month = month;
        warningLabel.setWrapText(true);
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Categories", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(month);
        rows.setAll(totals);
        long overBudgetCount = totals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();
        warningLabel.setText(overBudgetCount == 0
                ? "All categories are within target."
                : overBudgetCount + " categor" + (overBudgetCount == 1 ? "y is" : "ies are") + " over budget.");
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildCategoryManagement(), warningLabel);
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildCategoryManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Category name");
        TextField targetField = new TextField();
        targetField.setPromptText("Monthly target");
        Label status = new Label();
        status.setWrapText(true);

        TableView<BudgetService.CategoryTotal> table = buildTable();

        Button saveButton = new Button("Add category");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);
        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> refresh());

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                Category category = newSelection.getCategory();
                nameField.setText(category.getName());
                targetField.setText(category.getMonthlyTarget().toString());
                saveButton.setText("Update category");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add category");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            if (name.isEmpty()) {
                status.setText("Category name is required.");
                return;
            }
            try {
                BigDecimal monthlyTarget = new BigDecimal(targetField.getText().trim());
                BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    categoryRepository.add(new Category(name, monthlyTarget));
                    status.setText("Added category \"" + name + "\".");
                } else {
                    categoryService.update(selected.getCategory().getName(), new Category(name, monthlyTarget));
                    status.setText("Updated category \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Monthly target must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            try {
                categoryService.delete(selected.getCategory().getName());
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                status.setText("Deleted category \"" + selected.getCategory().getName() + "\".");
                refresh();
            } catch (IllegalStateException ex) {
                status.setText(ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Category:"), nameField, targetField, saveButton,
                deleteButton, refreshButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<BudgetService.CategoryTotal> buildTable() {
        TableView<BudgetService.CategoryTotal> table = new TableView<>(rows);

        TableColumn<BudgetService.CategoryTotal, String> nameCol = new TableColumn<>("Category");
